-- StudyCompass: College Scorecard import, part 1 of 6
-- Generated by scripts/scorecard/build-seed-sql.mjs from data/scorecard/universities.json.
-- Source: US Department of Education College Scorecard, data year 2024,
-- fetched 2026-10-06T06:55:42.188Z. Run after migration_007, files in order.

on conflict (scorecard_id) do update set
  country = excluded.country,
  city = excluded.city,
  state = excluded.state,
  ownership = excluded.ownership,
  us_region = excluded.us_region,
  tuition = excluded.tuition,
  tuition_in_state = excluded.tuition_in_state,
  avg_net_price = excluded.avg_net_price,
  acceptance_rate = excluded.acceptance_rate,
  sat_25 = excluded.sat_25,
  sat_75 = excluded.sat_75,
  avg_admitted_gpa = excluded.avg_admitted_gpa,
  min_ielts = excluded.min_ielts,
  living_cost_per_year = excluded.living_cost_per_year,
  student_size = excluded.student_size,
  completion_rate = excluded.completion_rate,
  median_earnings_10yr = excluded.median_earnings_10yr,
  popular_programs = excluded.popular_programs,
  degree_levels = excluded.degree_levels,
  source = excluded.source,
  data_year = excluded.data_year,
  fetched_at = excluded.fetched_at
where universities.created_by is null;
